CREATE TABLE customers (id TEXT PRIMARY KEY, customer_id TEXT UNIQUE, customer_name TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE pets (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL REFERENCES customers(id) ON DELETE CASCADE, pet_name TEXT NOT NULL, pet_type TEXT, breed TEXT, age REAL, address TEXT, medical_history TEXT, contact TEXT, preferred_groomer TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX pets_customer ON pets(customer_id);
CREATE TABLE appointments (id TEXT PRIMARY KEY, pet_id TEXT NOT NULL REFERENCES pets(id) ON DELETE CASCADE, day TEXT, date TEXT, type TEXT, groomer TEXT, price REAL CHECK(price IS NULL OR price >= 0), p_buy INTEGER, p_use INTEGER, p_left INTEGER, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX appointments_pet ON appointments(pet_id);
CREATE TABLE deleted_customers (id TEXT PRIMARY KEY, original_id TEXT NOT NULL, customer_id TEXT, customer_name TEXT NOT NULL, snapshot TEXT NOT NULL, deleted_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE membership_tiers (id TEXT PRIMARY KEY, name TEXT NOT NULL, min_spend REAL NOT NULL DEFAULT 0, discount_pct REAL DEFAULT 0 CHECK(discount_pct BETWEEN 0 AND 100), color TEXT, icon TEXT, perks TEXT);
CREATE TABLE members (id TEXT PRIMARY KEY, customer_id TEXT NOT NULL UNIQUE REFERENCES customers(id) ON DELETE CASCADE, email TEXT, date_of_birth TEXT, total_spend REAL DEFAULT 0, visit_count INTEGER DEFAULT 0, tier_id TEXT REFERENCES membership_tiers(id), marketing_consent INTEGER NOT NULL DEFAULT 0, last_visit_date TEXT, notes TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE user_profiles (id TEXT PRIMARY KEY REFERENCES user(id) ON DELETE CASCADE, role TEXT NOT NULL CHECK(role IN ('admin','customer')), customer_id TEXT UNIQUE REFERENCES customers(id) ON DELETE CASCADE, full_name TEXT, is_active INTEGER NOT NULL DEFAULT 1, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit_log (id TEXT PRIMARY KEY, actor_id TEXT NOT NULL, action TEXT NOT NULL, target_id TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
